std::string CleanHost(std::string_view raw) {
  std::string host(raw);
  for (char& c : host) c = static_cast<char>(tolower(static_cast<unsigned char>(c)));
  if (host.starts_with("www.")) host = host.substr(4);
  if (host.starts_with("m.")) host = host.substr(2);
  return host;
}

