std::string GetBuiltinFavicon(std::string_view raw_host) {
  const std::string host = CleanHost(raw_host);
  const auto& map = BuiltinMap();
  auto it = map.find(host);
  if (it != map.end()) return it->second;
  for (const auto& [domain, url] : map) {
    if (host.ends_with("." + domain)) return url;
  }
  return {};
}

std::string GetBuiltinFaviconsJson() {
  const auto& map = BuiltinMap();
  std::string json = "{";
  bool first = true;
  for (const auto& [domain, url] : map) {
    if (!first) json += ",";
    first = false;
    json += "\"" + domain + "\":\"" + url + "\"";
  }
  json += "}";
  return json;
}

